package password

import (
	"strings"
	"testing"

	"github.com/stretchr/testify/require"
	"golang.org/x/crypto/bcrypt"
)

const (
	testPassword = "correct horse battery staple"
	// testPasslibHash is a hash of testPassword generated by passlib's
	// pbkdf2_sha256.hash().
	testPasslibHash = "$pbkdf2-sha256$29000$eW/NeU.ptfb.HwOgtHZuTQ$vHtiZuoQvlZMighjw.jqxLaox6lVPNdPEzjOVFJFdrs"
	// testShortSaltHash is a hash of testPassword with an 8-byte salt,
	// generated by passlib's pbkdf2_sha256.hash().
	testShortSaltHash = "$pbkdf2-sha256$1000$hJDS.v./dw4$porxPr4IcvbE52FQs9in9WgGeDcebkslLfR0C69CK.Y"
	// testHtpasswdHash is a hash of testPassword generated by htpasswd -B.
	testHtpasswdHash = "$2y$10$kZBBAL5bfbo/mF0tzxBicuC0su8mjDvspG2NS6VXWMht1Sobmg4Iu"
)

func TestHash(t *testing.T) {
	hash, err := Hash(testPassword)
	require.NoError(t, err)
	require.True(t, strings.HasPrefix(hash, pbkdf2Prefix))

	h, err := parsePBKDF2(hash, true)
	require.NoError(t, err)
	require.Equal(t, pbkdf2Iterations, h.iterations)
	require.Len(t, h.salt, pbkdf2SaltLength)
	require.Len(t, h.key, pbkdf2KeyLength)

	ok, err := Verify(hash, testPassword)
	require.NoError(t, err)
	require.True(t, ok)

	ok, err = Verify(hash, "wrong")
	require.NoError(t, err)
	require.False(t, ok)

	// Each hash gets its own salt
	otherHash, err := Hash(testPassword)
	require.NoError(t, err)
	require.NotEqual(t, hash, otherHash)
}

func TestVerify(t *testing.T) {
	testBcryptHash, err := bcrypt.GenerateFromPassword(
		[]byte(testPassword),
		bcrypt.MinCost,
	)
	require.NoError(t, err)
	testCases := []struct {
		name     string
		hash     string
		password string
		assert   func(*testing.T, bool, error)
	}{
		{
			name:     "unrecognized hash",
			hash:     "not-a-hash",
			password: testPassword,
			assert: func(t *testing.T, _ bool, err error) {
				require.ErrorContains(t, err, "neither")
			},
		},
		{
			name:     "PBKDF2 hash; password matches",
			hash:     testPasslibHash,
			password: testPassword,
			assert: func(t *testing.T, ok bool, err error) {
				require.NoError(t, err)
				require.True(t, ok)
			},
		},
		{
			name:     "PBKDF2 hash; password does not match",
			hash:     testPasslibHash,
			password: "wrong",
			assert: func(t *testing.T, ok bool, err error) {
				require.NoError(t, err)
				require.False(t, ok)
			},
		},
		{
			name:     "htpasswd bcrypt hash; password matches",
			hash:     testHtpasswdHash,
			password: testPassword,
			assert: func(t *testing.T, ok bool, err error) {
				require.NoError(t, err)
				require.True(t, ok)
			},
		},
		{
			name:     "bcrypt hash; password matches",
			hash:     string(testBcryptHash),
			password: testPassword,
			assert: func(t *testing.T, ok bool, err error) {
				require.NoError(t, err)
				require.True(t, ok)
			},
		},
		{
			name:     "bcrypt hash; password does not match",
			hash:     string(testBcryptHash),
			password: "wrong",
			assert: func(t *testing.T, ok bool, err error) {
				require.NoError(t, err)
				require.False(t, ok)
			},
		},
	}
	for _, testCase := range testCases {
		t.Run(testCase.name, func(t *testing.T) {
			t.Parallel()
			ok, err := Verify(testCase.hash, testCase.password)
			testCase.assert(t, ok, err)
		})
	}
}

func TestValidate(t *testing.T) {
	require.NoError(t, Validate(testPasslibHash))
	require.Error(t, Validate("not-a-hash"))
}

func Test_parse(t *testing.T) {
	testBcryptHash, err := bcrypt.GenerateFromPassword(
		[]byte(testPassword),
		bcrypt.MinCost,
	)
	require.NoError(t, err)
	testCases := []struct {
		name        string
		hash        string
		fipsEnabled bool
		assert      func(*testing.T, parsedHash, error)
	}{
		{
			name: "PBKDF2 hash with too few fields",
			hash: "$pbkdf2-sha256$29000$eW/NeU.ptfb.HwOgtHZuTQ",
			assert: func(t *testing.T, _ parsedHash, err error) {
				require.ErrorContains(t, err, "does not have the form")
			},
		},
		{
			name: "PBKDF2 hash with too many fields",
			hash: testPasslibHash + "$extra",
			assert: func(t *testing.T, _ parsedHash, err error) {
				require.ErrorContains(t, err, "does not have the form")
			},
		},
		{
			name: "PBKDF2 hash with non-numeric iteration count",
			hash: "$pbkdf2-sha256$many$eW/NeU.ptfb.HwOgtHZuTQ$vHtiZuoQvlZMighjw.jqxLaox6lVPNdPEzjOVFJFdrs",
			assert: func(t *testing.T, _ parsedHash, err error) {
				require.ErrorContains(t, err, "invalid iteration count")
			},
		},
		{
			name: "PBKDF2 hash with zero iteration count",
			hash: "$pbkdf2-sha256$0$eW/NeU.ptfb.HwOgtHZuTQ$vHtiZuoQvlZMighjw.jqxLaox6lVPNdPEzjOVFJFdrs",
			assert: func(t *testing.T, _ parsedHash, err error) {
				require.ErrorContains(t, err, "invalid iteration count")
			},
		},
		{
			name: "PBKDF2 hash with undecodable salt",
			hash: "$pbkdf2-sha256$29000$not+ab64$vHtiZuoQvlZMighjw.jqxLaox6lVPNdPEzjOVFJFdrs",
			assert: func(t *testing.T, _ parsedHash, err error) {
				require.ErrorContains(t, err, "error decoding PBKDF2 salt")
			},
		},
		{
			name:        "PBKDF2 hash with short salt in FIPS mode",
			hash:        testShortSaltHash,
			fipsEnabled: true,
			assert: func(t *testing.T, _ parsedHash, err error) {
				require.ErrorContains(t, err, "not permitted in FIPS 140-3 mode")
			},
		},
		{
			name: "PBKDF2 hash with undecodable key",
			hash: "$pbkdf2-sha256$29000$eW/NeU.ptfb.HwOgtHZuTQ$not+ab64",
			assert: func(t *testing.T, _ parsedHash, err error) {
				require.ErrorContains(t, err, "error decoding PBKDF2 key")
			},
		},
		{
			name: "PBKDF2 hash with empty key",
			hash: "$pbkdf2-sha256$29000$eW/NeU.ptfb.HwOgtHZuTQ$",
			assert: func(t *testing.T, _ parsedHash, err error) {
				require.ErrorContains(t, err, "PBKDF2 key is 0 bytes")
			},
		},
		{
			name: "PBKDF2 hash with truncated key",
			hash: "$pbkdf2-sha256$29000$eW/NeU.ptfb.HwOgtHZuTQ$vHtiZu",
			assert: func(t *testing.T, _ parsedHash, err error) {
				require.ErrorContains(t, err, "PBKDF2 key is 4 bytes")
			},
		},
		{
			name: "PBKDF2 hash with short salt",
			hash: testShortSaltHash,
			assert: func(t *testing.T, h parsedHash, err error) {
				require.NoError(t, err)
				ok, err := h.matches(testPassword)
				require.NoError(t, err)
				require.True(t, ok)
			},
		},
		{
			name: "PBKDF2 hash",
			hash: testPasslibHash,
			assert: func(t *testing.T, h parsedHash, err error) {
				require.NoError(t, err)
				p, ok := h.(pbkdf2Hash)
				require.True(t, ok)
				require.Equal(t, 29000, p.iterations)
				// Re-encoding reproduces the original
				require.Equal(t, testPasslibHash, p.String())
			},
		},
		{
			name:        "PBKDF2 hash in FIPS mode",
			hash:        testPasslibHash,
			fipsEnabled: true,
			assert: func(t *testing.T, h parsedHash, err error) {
				require.NoError(t, err)
				require.IsType(t, pbkdf2Hash{}, h)
			},
		},
		{
			name:        "bcrypt hash in FIPS mode",
			hash:        string(testBcryptHash),
			fipsEnabled: true,
			assert: func(t *testing.T, _ parsedHash, err error) {
				require.ErrorContains(t, err, "not permitted in FIPS 140-3 mode")
			},
		},
		{
			name: "malformed bcrypt hash",
			hash: "$2a$10$tooshort",
			assert: func(t *testing.T, _ parsedHash, err error) {
				require.ErrorContains(t, err, "error parsing bcrypt hash")
			},
		},
		{
			name: "bcrypt hash",
			hash: string(testBcryptHash),
			assert: func(t *testing.T, h parsedHash, err error) {
				require.NoError(t, err)
				require.IsType(t, bcryptHash{}, h)
			},
		},
		{
			name: "unrecognized hash",
			hash: "not-a-hash",
			assert: func(t *testing.T, _ parsedHash, err error) {
				require.ErrorContains(t, err, "neither")
			},
		},
	}
	for _, testCase := range testCases {
		t.Run(testCase.name, func(t *testing.T) {
			t.Parallel()
			h, err := parse(testCase.hash, testCase.fipsEnabled)
			testCase.assert(t, h, err)
		})
	}
}
